uint32_t prUnicodeFullWidth(uint32_t codePoint) {
    uint32_t at = lowerBound(kWideFrom, uint32_t(countOf(kWideFrom)), codePoint);
    return at != countOf(kWideFrom) && kWideFrom[at] == codePoint ? kWideTo[at] : codePoint;
}

